script.text:
      &ScriptVoucherInit;
      &ScriptVoucherNumber;

function init$Voucher$(f) {initialize(f, 'ong_ba', 'ma_gd', 'loai_ct', 'status');}
function active$Voucher$(f) {
  objectBehavior$Voucher$Number.create(f, 'so_ct', 'ma_nk', 'ngay_lct', 'ma_dvcs');
  if (f._action == 'Edit') {
    f._currencyIdentity = f.getItemValue('ma_nt');
  }
  f.add_onResponseComplete(on$Voucher$ResponseComplete);
  f.add_commandEvent(on$Voucher$ExecuteCommand);
  f._tabContainer.add_activeTabChanged(onChange$Voucher$Tab);
  f._tabContainer._loaded = true;
  set$Voucher$DefaultValue(f);
   &APVSetReadOnlyFields;
      &APVHandleStatus;
  &VoucherLogHandleStatus;
  &ListCreate;
  &PostCreate;
  &UpdatedVoucherNumberByDate.Onchage;
}
function scatter$Voucher$(f) {
  f._voucherNumberBehavior.setFormLayout();
  if (f._action == 'Edit') f._currencyIdentity = f.getItemValue('ma_nt');
   &APVSetReadOnlyFields;
  set$Voucher$DefaultValue(f);
  &VoucherLogHandleStatus;
  &UpdatedVoucherNumberByDate.ResetCondition;
}
function close$Voucher$(f) {
  try {f.remove_commandEvent(on$Voucher$ExecuteCommand);} catch (ex) {}
  try {f.remove_onResponseComplete(on$Voucher$ResponseComplete);} catch (ex) {}
  objectBehavior$Voucher$Number.dispose(f);
  if (f._tabContainer) try {f._tabContainer.remove_activeTabChanged(onChange$Voucher$Tab);} catch (ex) {}
  &UpdatedVoucherNumberByDate.Dispose;
  &ListDispose;
  &PostDispose;
}
function on$Voucher$ExecuteCommand(sender, e) {
  var action = e.type.Action, f = sender, g = f.getItem('d{{xt}}')._controlBehavior;
  switch (action) {
    case 'Gather':
      g.setSequenceNumber('line_nbr');
      g.setContinuance('stt_rec0');
      break;
    case 'Shown':
      &ListShown;
      &PostShown;
      break;
    case 'Explore':
      &APVAddStatus;
      &VoucherLogHandleStatusExplore;
      break;
    default:
      break;
  }
}
function onChange$Voucher$Tab(sender, e) {
  sender.parentForm.focusWhenTabChanged(['d{{xt}}'&ListTabChange;&PostTabChange;]);
  &PostTabFocus;
}
function onChange$VoucherDate(o) {
  var f = o.parentForm, d = f.getItemValue('ngay_lct');
  if (d && !o._controlBehavior._inDateRange(d)) return;
  f.setItemValue('ngay_ct', f.getItemValue('ngay_lct'));
  &UpdatedVoucherNumberByDate.Request;
}
/* <flatten type="Javascript"> */
function onChange$Voucher$Transaction(o) {o.parentForm.request('Transaction', 'Transaction', ['ma_gd'], o);}
// TODO(onchange NT): khi đổi tiền NT → tính base qua f.executeExpression(['[t_tien]:=[t_tien_nt]*[ty_gia]', ...])
/* </flatten> */
function when$VoucherCopying(f) {
  &APVWhenVoucherCopying;
}


objectBehavior$Voucher$Currency = {
&ScriptCurrency;
  create: function(f) {
    var d = f.getItem('ngay_lct'), p = f.getItem('ngay_ct'), c = f.getItem('ma_nt'), r = f.getItem('ty_gia'), g = f.getItem('d{{xt}}')._controlBehavior;
    var v = f._currencyBehavior = $create(FastBusiness.AjaxControlExtender.Currency, {id: f._id + '_currencyBehavior', currencyDate: d, referenceDate: p, exchangeRate: r, form: f, baseCurrency: f._baseCurrency, flush: true}, null, null, c);
    // TODO(currency): danh sách cặp field tổng NT:base trên FORM — thêm/bớt theo nghiệp vụ
    v.set_currencyFields('t_tien_nt,t_tt_nt:t_tien,t_tt');

    var $dt = {};
    // TODO(currency): map cột _nt trên GRID detail — theo &CurrencyExpression.{X}Detail; của mẫu
    $dt.aGridFields = [['tien_nt', '[tien_nt]'], ['tien', '[tien]']];
    $dt.aTotalFields = [
      ['t_tien_nt', 'tien_nt', ''],
      ['t_tien', 'tien', '']
    ];
    $dt.aExpression = [];
    v.addGridFields(g, $dt.aGridFields);
    v.addTotalFields(g, $dt.aTotalFields);
    v.set_referenceFields(null);
    v.set_executeExpression($dt.aExpression);
    &CurrencyDateChanged;
  onCurrencySelected: function(sender, e) {
    var f = sender.get_element().parentForm;
    // TODO(currency): xử lý khi đổi ma_nt (vd refocus tab, đổi label cột)
  }
}


function on$Voucher$ResponseComplete(sender, e) {
  var f = e.object, context = e.type.Context, result = e.type.Result;
  switch (context) {
    case 'Loading':
      &VoucherNumberLoading;
      &APVSetVoucherDefaultValue;
      set$Voucher$Status$DefaultValue(f);
      break;
    case 'Scattering':
      &VoucherNumberScattering;
      &APVSetVoucherDefaultValue;
      &ListScattering;
      &PostScattering;
      set$Voucher$Status$DefaultValue(f);
      break;

      &VoucherNumberReading;
      &CurrencyResponse;

    case 'Transaction':
      f.setItemValue('loai_ct', result[0].Value);
      break;
    case 'Navigating':
      &ListRefresh;
      &PostRefresh;
      break;
    &ListResponseTicket;
    default:
      break;
  }
}
function set$Voucher$DefaultValue(f) {
  if (f._action == 'New') {
    var d = new Date();
    f.setItemValue('ngay_lct', d);
    f.setItemValue('ngay_ct', d);
  }
}
function set$Voucher$Status$DefaultValue(f) {
  var g = f.grid, o = f.getItem('status');
  // TODO(status): khóa/mở field theo trạng thái duyệt — mẫu xem &GNAPVEditVoucherHandleStatus; (phiên bản GN)
}
/* </flatten> */
      &APVFunctionScript;
      &ListScript;
      &PostScript;
      &UpdatedVoucherNumberByDate.Script;

